	for _, test := range []struct {
		path   string
		token  string
		status int
	}{{"/healthz", "", 200}, {"/readyz", "", 401}, {"/readyz", token, 200}} {
		request := httptest.NewRequest(http.MethodGet, test.path, http.NoBody)
		if test.token != "" {
			request.Header.Set("Authorization", "Bearer "+test.token)
		}
		response := httptest.NewRecorder()
		server.Handler().ServeHTTP(response, request)
		if response.Code != test.status {
			t.Fatalf("%s status = %d body=%s", test.path, response.Code, response.Body)
		}
	}
}

func TestCreateRunRequiresRoleStrictJSONAndIdempotency(t *testing.T) {
	server, workflowStore, runtimeLedger, token := testServer(t, RoleOperator)
	runID, key := uuid.NewString(), uuid.NewString()
	body := `{"run_id":"` + runID + `","decision_timestamp":"2026-07-29T12:00:00Z"}`
	request := httptest.NewRequest(http.MethodPost, "/v1/runs", strings.NewReader(body))
	request.Header.Set("Authorization", "Bearer "+token)
	request.Header.Set("Idempotency-Key", key)
	response := httptest.NewRecorder()
	server.Handler().ServeHTTP(response, request)
	if response.Code != http.StatusCreated || len(workflowStore.runCommands) != 1 ||
		runtimeLedger.begins != 1 || runtimeLedger.completes != 1 {
		t.Fatalf("response=%d %s commands=%d runtime=%#v",
			response.Code, response.Body, len(workflowStore.runCommands), runtimeLedger)
	}
	command := workflowStore.runCommands[0].(workflow.CreateRun)
	if command.ID != runID || command.Meta.Actor.Kind != workflow.ActorHuman {
		t.Fatalf("command = %#v", command)
	}

	bad := httptest.NewRequest(http.MethodPost, "/v1/runs",
		strings.NewReader(`{"run_id":"`+runID+`","decision_timestamp":"2026-07-29T12:00:00Z","unknown":true}`))
	bad.Header.Set("Authorization", "Bearer "+token)
	bad.Header.Set("Idempotency-Key", uuid.NewString())
	badResponse := httptest.NewRecorder()
	server.Handler().ServeHTTP(badResponse, bad)
	if badResponse.Code != http.StatusBadRequest {
		t.Fatalf("strict JSON status = %d: %s", badResponse.Code, badResponse.Body)
	}
}

func TestCreateRunRejectsMissingKeyAndWrongRole(t *testing.T) {
	for _, roles := range [][]Role{{RoleOperator}, {RoleApprover}} {
		server, _, _, token := testServer(t, roles...)
		request := httptest.NewRequest(http.MethodPost, "/v1/runs",
			strings.NewReader(`{"run_id":"`+uuid.NewString()+`","decision_timestamp":"2026-07-29T12:00:00Z"}`))
		request.Header.Set("Authorization", "Bearer "+token)
		if roles[0] == RoleApprover {
			request.Header.Set("Idempotency-Key", uuid.NewString())
		}
		response := httptest.NewRecorder()
		server.Handler().ServeHTTP(response, request)
		want := http.StatusBadRequest
		if roles[0] == RoleApprover {
			want = http.StatusForbidden
		}
		if response.Code != want {
			t.Fatalf("roles=%v status=%d body=%s", roles, response.Code, response.Body)
		}
	}
}

// Package orchestration drives restart-safe deterministic runtime stages.
package orchestration

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"time"

	"github.com/Standard-Syntax/basic/go/internal/runtime"
	"github.com/Standard-Syntax/basic/go/internal/workflow"
	"github.com/google/uuid"
)

const (
	StageStart                 = "start"
	StageImplementationRequest = "implementation_request"
	StageReasoning             = "implementation_reasoning"
	StageExecution             = "execution"
	StageVerification          = "verification"
	StageReview                = "review"
	StageAwaitingApproval      = "awaiting_approval"
)

var orderedStages = []string{
	StageStart, StageImplementationRequest, StageReasoning, StageExecution,
	StageVerification, StageReview, StageAwaitingApproval,
}

type JobLedger interface {
	Claim(context.Context, string, time.Time, time.Duration) (runtime.Job, bool, error)
	CompleteAndEnqueue(
		context.Context, string, string, uint64, workflow.ArtifactRef, *runtime.Job, time.Time,
	) error
	Retry(context.Context, string, string, uint64, time.Time) error
	Fail(context.Context, string, string, uint64, workflow.ArtifactRef, time.Time) error
}

type ArtifactStore interface {
	Put(context.Context, []byte) (workflow.ArtifactRef, error)
}

type Handler interface {
	Handle(context.Context, runtime.Job, Identities) (workflow.ArtifactRef, error)
}

type HandlerFunc func(context.Context, runtime.Job, Identities) (workflow.ArtifactRef, error)

func (f HandlerFunc) Handle(
	ctx context.Context, job runtime.Job, ids Identities,
) (workflow.ArtifactRef, error) {
	return f(ctx, job, ids)
}

type Identities struct {
	ActivityID     string `json:"activity_id"`
	InvocationID   string `json:"invocation_id"`
	ExecutionID    string `json:"execution_id"`
	VerificationID string `json:"verification_id"`
	ReviewID       string `json:"review_id"`
	CommandID      string `json:"command_id"`
}

type Config struct {
	OwnerID        string
	ClaimTTL       time.Duration
	PollInterval   time.Duration
	MaxRetries     uint32
	InitialBackoff time.Duration
}

type Reconciler struct {
	config    Config
	ledger    JobLedger
	artifacts ArtifactStore
	handlers  map[string]Handler
	logger    *slog.Logger
	now       func() time.Time
}

func New(
	config Config, ledger JobLedger, artifacts ArtifactStore,
	handlers map[string]Handler, logger *slog.Logger,
) (*Reconciler, error) {
	if _, err := uuid.Parse(config.OwnerID); err != nil || config.ClaimTTL <= 0 ||
		config.PollInterval <= 0 || config.MaxRetries == 0 || config.InitialBackoff <= 0 {
		return nil, errors.New("invalid reconciler configuration")
	}
	for _, stage := range orderedStages {
		if handlers[stage] == nil {
			return nil, fmt.Errorf("missing stage handler %q", stage)
		}
	}
	if logger == nil {
		logger = slog.Default()
	}
	return &Reconciler{
		config: config, ledger: ledger, artifacts: artifacts,
		handlers: handlers, logger: logger, now: time.Now,
	}, nil
}

func (r *Reconciler) Run(ctx context.Context) error {
	timer := time.NewTicker(r.config.PollInterval)
	defer timer.Stop()
	for {
		worked, err := r.Once(ctx)
		if err != nil {
			r.logger.Error("runtime reconciliation failed", "error", err)
		}
		if worked {
			continue
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-timer.C:
		}
	}
}

func (r *Reconciler) Once(ctx context.Context) (bool, error) {
	now := r.now().UTC()
	job, found, err := r.ledger.Claim(ctx, r.config.OwnerID, now, r.config.ClaimTTL)
	if err != nil || !found {
		return false, err
	}
	ids := StableIdentities(job)
	logger := r.logger.With(
		"run_id", job.RunID, "stage", job.Stage, "attempt", job.Attempt,
		"job_id", job.ID, "fencing_token", job.FencingToken,
	)
	if job.TaskID != nil {
		logger = logger.With("task_id", *job.TaskID)
	}
	var result workflow.ArtifactRef
	var handleErr error
	handler, ok := r.handlers[job.Stage]
	if !ok {
		handleErr = fmt.Errorf("no handler registered for stage %q", job.Stage)
	} else {
		handlerCtx, cancel := context.WithTimeout(ctx, r.config.ClaimTTL)
		result, handleErr = handler.Handle(handlerCtx, job, ids)
		cancel()
	}
	if handleErr == nil {
		var nextJob *runtime.Job
		if next, ok := nextStage(job.Stage); ok {
			nextJob = &runtime.Job{
				ID:    StableID(job.RunID, taskValue(job.TaskID), fmt.Sprint(job.Attempt), next, "job"),
				RunID: job.RunID, TaskID: job.TaskID, Attempt: job.Attempt,
				Stage: next, AvailableAt: r.now().UTC(),
			}
		}
		if err := r.ledger.CompleteAndEnqueue(
			ctx, job.ID, r.config.OwnerID, job.FencingToken, result, nextJob, r.now(),
		); err != nil {
			return true, err
		}
		logger.Info("runtime stage completed", "result_digest", result.Digest)
		return true, nil
	}
	if errors.Is(handleErr, context.Canceled) || errors.Is(handleErr, context.DeadlineExceeded) {
		return true, handleErr
	}
	if job.RetryCount+1 < r.config.MaxRetries {
		backoff := r.config.InitialBackoff << job.RetryCount
		if backoff > time.Minute {
			backoff = time.Minute
		}
		err := r.ledger.Retry(
			ctx, job.ID, r.config.OwnerID, job.FencingToken, r.now().Add(backoff),
		)
		logger.Warn("runtime stage scheduled for retry", "error", handleErr, "backoff", backoff)
		return true, err
	}
	body, marshalErr := json.Marshal(struct {
		SchemaVersion string      `json:"schema_version"`
		Job           runtime.Job `json:"job"`
		Error         string      `json:"error"`
	}{SchemaVersion: "runtime_failure.v1", Job: job, Error: handleErr.Error()})
	if marshalErr != nil {
		return true, marshalErr
	}
	failure, err := r.artifacts.Put(ctx, body)
	if err != nil {
		return true, err
	}
	if err := r.ledger.Fail(
		ctx, job.ID, r.config.OwnerID, job.FencingToken, failure, r.now(),
	); err != nil {
		return true, err
	}
	logger.Error("runtime stage exhausted retries", "failure_digest", failure.Digest)
	return true, nil
}

func StableIdentities(job runtime.Job) Identities {
	parts := []string{job.RunID, taskValue(job.TaskID), fmt.Sprint(job.Attempt), job.Stage}
	return Identities{
		ActivityID:     StableID(append(parts, "activity")...),
		InvocationID:   StableID(append(parts, "invocation")...),
		ExecutionID:    StableID(append(parts, "execution")...),
		VerificationID: StableID(append(parts, "verification")...),
		ReviewID:       StableID(append(parts, "review")...),
		CommandID:      StableID(append(parts, "command")...),
	}
}

func StableID(parts ...string) string {
	return uuid.NewSHA1(uuid.NameSpaceOID, []byte(fmt.Sprintf("%q", parts))).String()
}

func nextStage(stage string) (string, bool) {
	for index, value := range orderedStages {
		if value == stage && index+1 < len(orderedStages) {
			return orderedStages[index+1], true
		}
	}
	return "", false
}

func taskValue(task *string) string {
	if task == nil {
		return "-"
	}
	return *task
}
// Command workflow-service runs the durable first-slice reconciler.
package main

import (
	"context"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"log/slog"
	"os"
	"os/signal"
	"path/filepath"
	"syscall"
	"time"

	"github.com/Standard-Syntax/basic/go/internal/artifact"
	"github.com/Standard-Syntax/basic/go/internal/orchestration"
	"github.com/Standard-Syntax/basic/go/internal/runtime"
	"github.com/Standard-Syntax/basic/go/internal/workflow"
	"github.com/jackc/pgx/v5/pgxpool"
)

type config struct {
	DatabaseURL      string `json:"database_url"`
	ArtifactRoot     string `json:"artifact_root"`
	OwnerID          string `json:"owner_id"`
	MaxArtifactBytes int64  `json:"max_artifact_bytes"`
}

func main() {
	os.Exit(mainExit())
}

func mainExit() int {
	slog.SetDefault(slog.New(slog.NewJSONHandler(os.Stdout, nil)))
	configPath := flag.String("config", "", "absolute path to strict JSON configuration")
	flag.Parse()
	if *configPath == "" {
		slog.Error("configuration is required")
		return 2
	}
	value, err := loadConfig(*configPath)
	if err != nil {
		slog.Error("load configuration", "error", err)
		return 2
	}
	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()
	if err := run(ctx, value); err != nil && !errors.Is(err, context.Canceled) {
		slog.Error("workflow service stopped", "error", err)
		return 1
	}
	return 0
}

func loadConfig(path string) (config, error) {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return config{}, errors.New("config path must be clean and absolute")
	}
	file, err := os.Open(path)
	if err != nil {
		return config{}, err
	}
	defer file.Close()
	decoder := json.NewDecoder(io.LimitReader(file, 1<<20))
	decoder.DisallowUnknownFields()
	var value config
	if err := decoder.Decode(&value); err != nil {
		return config{}, err
	}
	var trailing any
	if err := decoder.Decode(&trailing); !errors.Is(err, io.EOF) {
		return config{}, errors.New("configuration has trailing content")
	}
	if value.DatabaseURL == "" || !filepath.IsAbs(value.ArtifactRoot) ||
		filepath.Clean(value.ArtifactRoot) != value.ArtifactRoot || value.OwnerID == "" {
		return config{}, errors.New("incomplete configuration")
	}
	return value, nil
}

func run(ctx context.Context, value config) error {
	migrateCtx, cancelMigrate := context.WithTimeout(ctx, 30*time.Second)
	err := workflow.Migrate(migrateCtx, value.DatabaseURL)
	cancelMigrate()
	if err != nil {
		return fmt.Errorf("migrate workflow: %w", err)
	}
	pool, err := pgxpool.New(ctx, value.DatabaseURL)
	if err != nil {
		return err
	}
	defer pool.Close()
	pingCtx, cancelPing := context.WithTimeout(ctx, 30*time.Second)
	err = pool.Ping(pingCtx)
	cancelPing()
	if err != nil {
		return err
	}
	artifacts, err := artifact.NewStore(value.ArtifactRoot, value.MaxArtifactBytes)
	if err != nil {
		return err
	}
	defer artifacts.Close()
	handlers := make(map[string]orchestration.Handler)
	for _, stage := range []string{
		orchestration.StageStart, orchestration.StageImplementationRequest,
		orchestration.StageReasoning, orchestration.StageExecution,
		orchestration.StageVerification, orchestration.StageReview,
		orchestration.StageAwaitingApproval,
	} {
		current := stage
		handlers[stage] = orchestration.HandlerFunc(func(
			ctx context.Context, job runtime.Job, ids orchestration.Identities,
		) (workflow.ArtifactRef, error) {
			body, err := json.Marshal(struct {
				SchemaVersion string                   `json:"schema_version"`
				Stage         string                   `json:"stage"`
				JobID         string                   `json:"job_id"`
				Identities    orchestration.Identities `json:"identities"`
			}{"runtime_checkpoint.v1", current, job.ID, ids})
			if err != nil {
				return workflow.ArtifactRef{}, err
			}
			return artifacts.Put(ctx, body)
		})
	}
	reconciler, err := orchestration.New(orchestration.Config{
		OwnerID: value.OwnerID, ClaimTTL: 30 * time.Second,
		PollInterval: 250 * time.Millisecond, MaxRetries: 5, InitialBackoff: time.Second,
	}, runtime.NewLedger(pool), artifacts, handlers, slog.Default())
	if err != nil {
		return err
	}
	slog.Info("workflow service ready", "owner_id", value.OwnerID)
	return reconciler.Run(ctx)
}

