		}
	}
	for _, binding := range []*ArtifactRef{
		r.Execution, r.Verification, r.Review, r.Approval, r.Publication, r.Merge,
	} {
		if binding != nil {
			if err := binding.Validate(); err != nil {
				return err
			}
		}
