+		),
+		ApprovedTaskId: input.TaskID, ApprovedTaskDigest: input.ApprovedTask.Digest,
+		ApprovedSpecificationId: input.ApprovedSpecificationID,
+		ApprovedSpecificationDigest: input.ApprovedSpecification.Digest,
